79	template <FIA_LAYOUT LAYOUT_T>
80	__aicore__ inline bool IsSkipCal(uint64_t gS1Idx,
81	                                 uint64_t actMSize,
82	                                 uint64_t s2Start,
83	                                 uint64_t s2DealSize,
84	                                 const RunInfo &info,
85	                                 const ConstInfo &constInfo)
86	{
87	    // 处理sinkTensor的循环，sink全部参与运算，不允许跳过
88	    if (unlikely(info.isSinkTensor)) {
89	        return false;
90	    }
91	
92	    // 计算有效 s1Start、s1End
93	    int64_t s1GFirstToken = gS1Idx;
94	    int64_t s1GLastToken = s1GFirstToken + actMSize;
95	
96	    int64_t s1FirstToken = 0;
97	    int64_t s1LastToken = 0;
98	    if constexpr (unlikely(LAYOUT_T == FIA_LAYOUT::BNSD || LAYOUT_T == FIA_LAYOUT::NBSD ||
99	                           LAYOUT_T == FIA_LAYOUT::NTD)) {
100	        if (s1GFirstToken / info.actS1Size == s1GLastToken / info.actS1Size) {
101	            // start and end locate in one G
102	            s1FirstToken = s1GFirstToken % info.actS1Size;
103	            s1LastToken = s1GLastToken % info.actS1Size;
104	        } else {
105	            // start and end locate in tow or more G, but working same as crossing one complete block
106	            s1FirstToken = 0;
107	            s1LastToken = info.actS1Size;
108	        }
109	    } else {
110	        s1FirstToken = static_cast<int64_t>(s1GFirstToken / constInfo.gSize);
111	        s1LastToken = static_cast<int64_t>(s1GLastToken / constInfo.gSize);
112	    }
113	
114	    // 计算有效的S2边界
115	    int64_t validS2FirstToken = s1FirstToken - info.preTokenLeftUp - 1;
116	    int64_t validS2LastToken = s1LastToken + info.nextTokenLeftUp;
117	    int64_t actS2LastToken = static_cast<int64_t>(s2Start + s2DealSize - 1);
118	
119	    // 稀疏边界检查：如果当前S2块完全在有效S2边界外，则跳过计算
120	    if (unlikely((actS2LastToken <= validS2FirstToken) || (validS2LastToken <= s2Start))) {
121	        return true; // 需要跳过
122	    }
123	    return false; // 不需要跳过，需要计算
124	}
