    uint32_t baseMetadata[BASE_METADATA_SIZE];
};
} // namespace detail

static_assert(FIASINK_META_SIZE * sizeof(FIASINK_METADATA_T) >= sizeof(detail::FiaSinkMetaData));
} // namespace optiling

