bool CheckGqaDSupport(gert::TilingContext *context)
{
    int64_t queryD = 0;
    int64_t queryRopeD = 0;
    int64_t valueD = 0;
    if (GetQkvD(context, queryD, queryRopeD, valueD) != true) {
